// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
let estado = {};
const CLAVE = "app";
const TOTAL_FILAS = 20;
const COLUMNAS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

// Inicializa el estado con todas las celdas vacías, pero presentes.
function inicializarEstado() {
    estado = {};
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        for (const col of COLUMNAS) {
            const cellId = `${col}${r}`;
            estado[cellId] = ''; // Inicializa cada celda con un valor vacío
        }
    }
}

/**
 * Actualiza el estado interno de una celda específica.
 * @param {string} cellId - ID de la celda (Ej: 'A1').
 * @param {string} value - El nuevo valor ingresado por el usuario o calculado.
 */
function actualizarCelda(cellId, value) {
    if (!estado.hasOwnProperty(cellId)) {
        console.warn(`Intento de actualizar una celda no inicializada: ${cellId}`);
        return;
    }
    // Actualizamos el estado con el valor recibido (el texto puro o calculado).
    estado[cellId] = value;
    guardar();
    // Después de la lógica, siempre renderizamos para asegurar que cualquier formato o cálculo se aplique.
    render();
}


function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            const loadedState = JSON.parse(s);
            // Aseguramos que el estado cargado tenga la estructura completa, rellenando lo faltante.
            inicializarEstado();
            for (const cellId in loadedState) {
                if (loadedState.hasOwnProperty(cellId)) {
                    estado[cellId] = loadedState[cellId];
                }
            }
        } else {
             // Si no hay datos guardados, inicializamos el estado vacío completo.
            inicializarEstado();
        }
    } catch (e) { 
        console.error("Error al cargar el estado:", e);
        inicializarEstado(); // Fallback seguro
    } 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) { 
        console.error("Error al guardar el estado:", e); 
    } 
}


/**
 * Evalúa una fórmula estilo Excel en castellano si detecta patrones conocidos.
 * @param {string} formula - El contenido de la celda.
 * @returns {number|string} El resultado calculado o la fórmula original si no se puede evaluar.
 */
function evalFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return formula; // No es una fórmula, devolver texto puro.
    }

    let content = formula.substring(1).trim();

    // 1. Manejo de SUMA (SUMA)
    const sumMatch = content.match(/SUMA\(([^)]+)\)/i);
    if (sumMatch && sumMatch[0].toUpperCase().startsWith("SUMA")) {
        const rangeContent = sumMatch[1]; // Contenido dentro de los paréntesis

        // Detectar si es un rango simple (A1:A3) o una lista separada por ; (A1;B2;C3)
        let cellsToProcess = [];
        if (rangeContent.includes(':')) {
            const [startRef, endRef] = rangeContent.split(':').map(r => r.trim());

            // Asumimos que el rango es en una sola columna para simplicidad de implementación del fix.
            const startColChar = startRef.match(/[A-Z]/)[0];
            const endColChar = endRef.match(/[A-Z]/)[0];

            if (startColChar === endColChar) {
                 cellsToProcess = [];
                 let startRow = parseInt(startRef.replace(/[A-Z]/g, ''));
                 let endRow = parseInt(endRef.replace(/[A-Z]/g, ''));

                 for (let r = startRow; r <= endRow; r++) {
                     cellsToProcess.push(`${startColChar}${r}`);
                 }
            } else {
                // Si el rango abarca más de una columna, se ignora la funcionalidad compleja por límite del scope
                return formula; 
            }
        } else {
            // Lista de celdas separadas por ;
            cellsToProcess = rangeContent.split(';').map(r => r.trim()).filter(Boolean);
        }

        let sumValue = 0;
        for (const ref of cellsToProcess) {
            if (estado.hasOwnProperty(ref)) {
                const val = parseFloat(estado[ref]);
                if (!isNaN(val)) {
                    sumValue += val;
                }
            }
        }
        return sumValue;
    }

    // 2. Manejo de operaciones aritméticas simples (A1-B1, A1*B1, etc.)
    try {
        let expression = content;

        // Reemplazar referencias de celdas por sus valores numéricos actuales en el estado.
        expression = expression.replace(/([A-Z]+[0-9]+)/g, (match) => {
            const value = estado[match];
            if (value !== undefined && !isNaN(parseFloat(value))) {
                return parseFloat(value);
            }
            // Si no se encuentra o no es número, mantener la referencia para que eval falle si es necesario.
            return match; 
        });

        // Usamos new Function() para evaluar el resultado de la expresión aritmética segura.
        const result = new Function('return (' + expression + ')')();
        if (typeof result === 'number' && isFinite(result)) {
            return result;
        }
    } catch (e) {
        // Si falla la evaluación, simplemente devolvemos el texto original de la fórmula.
        return formula; 
    }

    // Fallback: Si no se pudo evaluar o no es un patrón conocido.
    return formula;
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('td[data-cell]');

    cells.forEach(cell => {
        const cellId = cell.getAttribute('data-cell');
        const currentValueInState = estado[cellId];

        // Regla: No redibujar si el elemento está activo (el usuario lo está editando).
        if (document.activeElement === cell) {
            return; 
        }

        // CALCULAR EL VALOR A MOSTRAR ANTES DE PONERLO EN EL DOM.
        const displayValue = evalFormula(currentValueInState);

        // Establecer el contenido visible del TD desde el estado (o su cálculo).
        cell.textContent = displayValue;
    });
}


// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const spreadsheetBody = document.querySelector('tbody');

    if (!spreadsheetBody) return;

    /**
     * Manejador genérico para cualquier cambio en las celdas editables.
     * Solo se dispara cuando el usuario deja de escribir o termina de editar (blur/change).
     */
    const handleCellChange = (event) => {
        // 1. Identificar la celda que disparó el evento.
        const target = event.target;
        if (target.tagName !== 'TD' || !target.hasAttribute('data-cell')) {
            return;
        }

        const cellId = target.getAttribute('data-cell');
        // 2. Obtener el valor *real* que se quedó en el DOM después de la edición.
        let newValue = target.textContent.trim();

        // 3. Lógica: Actualizar el estado con el valor finalizado.
        actualizarCelda(cellId, newValue);
    };


    // Usamos Event Delegation para escuchar eventos sobre todos los TDs sin adjuntar listeners individuales.
    spreadsheetBody.addEventListener('blur', handleCellChange);
    spreadsheetBody.addEventListener('change', handleCellChange);

    // Nota: El evento 'input' no se usa aquí, ya que el requerimiento es guardar solo al terminar de editar (blur/change).
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
