 * @param {string} formula - La cadena de la fórmula (Ej: "=SUMA(A1:A3)").
 * @returns {number|string} El resultado calculado como número, o el valor original si no es una fórmula válida.
 */
function evaluateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return formula; // No es una fórmula o está vacío
    }

    let expression = formula.substring(1).trim();

    // 1. Manejo de SUMA() y argumentos (rango A1:B2 o lista A1;B2)
    const sumRegex = /SUMA\(([^)]+)\)/i;
    if (sumRegex.test(expression)) {
        const match = expression.match(sumRegex);
        let argsString = match[1];

        // Si el argumento contiene un rango (ej: A1:B2), lo procesamos de manera especial.
        if (argsString.includes(':')) {
            const rangeMatch = argsString.match(/([A-Z]+[0-9]+):?([A-Z]+[0-9]*)/);
            if (rangeMatch) {
                const startCellId = rangeMatch[1];
                const endCellId = rangeMatch[2] || rangeMatch[1]; // Si solo hay A1, el rango es 1 celda

                // Convertir IDs a coordenadas de fila/columna para iterar
                const [startColChar, startRowStr] = startCellId.toUpperCase().match(/([A-Z]+)([0-9]+)/);
                const [endColChar, endRowStr2] = endCellId.toUpperCase().match(/([A-Z]+)([0-9]+)/);

                let colStart = getColumnIndex(startColChar);
                let rowStart = parseInt(startRowStr);
                let colEnd = getColumnIndex(endColChar);
                let rowEnd = parseInt(endRowStr2);

                // Ajustar límites de iteración si los rangos no son perfectos (ej: A1 a C3)
                if (colStart === undefined || colEnd === undefined) {
                    return NaN; // Error en la lectura del rango.
                }


                let sum = 0;
                for (let r = rowStart; r <= Math.max(rowStart, parseInt(endRowStr2)); r++) {
                    // Iterar sobre columnas desde el inicio hasta el final del rango
                    for (let i = colStart; i <= colEnd; i++) {
                        const colChar = getColumnChar(i);
                        const cellId = `${colChar}${r}`;
                        if (estado.hasOwnProperty(cellId)) {
                            const value = parseFloat(estado[cellId]) || 0;
                            sum += value;
                        }
                    }
                }
                return sum;
            }
        }

        // Si es una lista de celdas separadas por punto y coma (A1;B2;C3)
        let cellsToSum = argsString.split(';') || [];
        let sum = 0;
        for (const cellId of cellsToSum) {
            cellId = cellId.trim();
            if (estado.hasOwnProperty(cellId)) {
                const value = parseFloat(estado[cellId]) || 0;
                sum += value;
            }
        }
        return sum;
    }

    // 2. Manejo de Operaciones Aritméticas simples (=A1+B2*C3)
    // Sustituir referencias de celda por sus valores numéricos en la expresión para evaluar con JavaScript.
    let mathExpression = expression;
    const cellRegex = /([A-Z]+[0-9]+)/g; // Coincide con A1, B23, etc.

    mathExpression = mathExpression.replace(cellRegex, (match) => {
        if (estado.hasOwnProperty(match)) {
            const value = parseFloat(estado[match]);
            return isNaN(value) ? '0' : value; // Reemplaza la referencia por el número o 0 si no es numérico
        }
        // Si la celda referenciada no existe en el estado, tratamos como 0 para evitar NaN.
        return '0'; 
    });

    try {
        // Usamos eval() de forma controlada aquí porque solo estamos evaluando strings construidos internamente desde el estado.
        const result = Function(`return ${mathExpression}`)();
        if (isNaN(result)) return formula; // Si la evaluación resulta en NaN, devolvemos la fórmula original.
        return result;
    } catch (e) {
        console.error("Error evaluando expresión matemática:", e);
        return formula; // Fallback: devolver la fórmula si hay error de sintaxis
    }
}

// Helper functions para parsing de rangos
function getColumnIndex(colChar) {
    let count = 0;
    for (let i = 65; i < 91; i++) { // A=65, B=66, ... Z=90
        if (String.fromCharCode(i) === colChar) {
            return ++count;
        }
    }
    return undefined;
}

function getColumnChar(index) {
    // Convierte índice numérico (1=A, 2=B, ...) a caracter de columna ('A', 'B', ...)
    let charCode = 64 + index; // ASCII de 'A' es 65
    return String.fromCharCode(charCode);
}
