/**
 * Intenta evaluar una fórmula de hoja de cálculo almacenada en el estado.
 * @param {string} cellId - ID de la celda que contiene la fórmula (Ej: 'B4').
 * @returns {string|null} El resultado calculado como string, o null si no es una fórmula reconocida.
 */
function calculateFormula(cellId) {
    const formula = estado[cellId];

    if (!formula || !formula.startsWith('=')) {
        return null; // No es una fórmula
    }

    // 1. Limpiar la fórmula de '=' inicial
    let rawFormula = formula.substring(1);

    try {
        // Manejo simple para SUMA(rango) o SUMA(c1; c2; ...)
        if (rawFormula.toUpperCase().startsWith('SUMA')) {
            const argsString = rawFormula.match(/\((.*)\)/)[1]; // Captura el contenido entre paréntesis

            let valuesToSum = [];
            // Divide por punto y coma, que es el separador de celdas sueltas en castellano
            const cellReferences = argsString.split(';'); 

            for (const ref of cellReferences) {
                const trimmedRef = ref.trim();
                if (trimmedRef) {
                    // Asume que la referencia es válida y busca el valor en el estado
                    if (estado.hasOwnProperty(trimmedRef)) {
                        valuesToSum.push(parseFloat(estado[trimmedRef]) || 0);
                    } else {
                         console.warn(`Referencia de celda no encontrada: ${trimmedRef}`);
                    }
                }
            }

            const sum = valuesToSum.reduce((acc, val) => acc + val, 0);
            return String(sum);
        }
        // Añadir lógica para otras fórmulas (resta, multiplicación, división) si fuera necesario
        // Ejemplo: Si se detectan solo referencias de celda sin función, se puede intentar evaluar la expresión matemática.

    } catch (e) {
        console.error(`Error al calcular fórmula en ${cellId}:`, e);
        return null; // Falló el cálculo, devolverá la fórmula cruda más tarde
    }

    return null;
}
