function evalFormula(formula) {
    // Regex para encontrar referencias de celda como A1, B12, etc.
    const cellRegex = /([A-Z]+[0-9]+)/g;
    let expression = formula;

    // Recopila todas las referencias únicas necesarias para la sustitución
    const refs = [...new Set(formula.match(cellRegex) || [])];

    // Proceso de sustitución: Reemplaza $REF con el valor real de estado['$REF']
    for (const ref of refs) {
        if (!estado[ref]) continue;
        let value = estado[ref];

        // Creamos una expresión regular global para reemplazar la referencia.
        const regex = new RegExp('\\b' + ref + '\\b', 'g');
        let replacement;

        // Determinamos cómo sustituir el valor en la cadena de expresión:
        if (typeof value === 'string' && !isNaN(parseFloat(value)) && isFinite(value)) {
             replacement = value; // Si es un número válido, lo mantenemos como string numérico.
        } else {
            // Si es texto o vacío, lo envolvemos en comillas para evitar errores de sintaxis en el eval (aunque fallará si se espera una operación matemática).
            replacement = JSON.stringify(value); 
        }

        expression = expression.replace(regex, replacement);
    }

    try {
        // Ejecuta la cadena resultante como JavaScript para obtener el valor calculado.
        return eval(expression); 
    } catch (e) {
        console.error("Error de evaluación de fórmula:", e);
        return null; // Indica fallo en la evaluación
    }
}
