function recalculateDependencies(updatedCellId) {
    let updatedCells = [updatedCellId];
    const MAX_DEPTH = 5; // Limita las iteraciones para evitar bucles infinitos.
    let currentDepth = 0;

    while (currentDepth < MAX_DEPTH && updatedCells.length > 0) {
        const nextUpdatedCells = [];
        // Usamos un Set para asegurar que procesamos cada celda fuente solo una vez en este ciclo.
        const cellsToCheck = [...new Set(updatedCells)]; 

        for (const sourceCellId of cellsToCheck) {
            // Iterar sobre todas las celdas posibles para buscar dependencias
            for (let r = 1; r <= TOTAL_FILAS; r++) {
                for (const col of COLUMNAS) {
                    const targetCellId = `${col}${r}`;

                    if (targetCellId === sourceCellId) continue; 

                    // Comprobar si la celda objetivo es una fórmula y referencia la fuente.
                    let targetFormula = estado[targetCellId];
                    if (!targetFormula || !typeof targetFormula.startsWith('=')) {
                        continue; 
                    }

                    // Verificación simple de dependencia por coincidencia de texto (la columna).
                    const sourceColLetter = sourceCellId.charAt(0);
                    const referenceRegex = new RegExp('\\b' + sourceColLetter + '[0-9]+[a-z]*\\b', 'i');

                    if (referenceRegex.test(targetFormula)) {
                        // Found dependency! Calculate it.
                        let calculatedResult = evalFormula(targetFormula);

                        if (calculatedResult !== null) {
                            const currentStoredValue = estado[targetCellId];
                            // Solo actualizamos si el cálculo produce un resultado diferente al almacenado.
                            if (currentStoredValue !== calculatedResult && String(currentStoredValue) !== String(calculatedResult)) {
                                // Actualizar estado y añadir a la lista de dependencias para la próxima iteración.
                                estado[targetCellId] = calculatedResult; 
                                nextUpdatedCells.push(targetCellId);
                            }
                        }
                    }
                }
            }
        }

        // Eliminar duplicados y preparar las IDs que actualizaron en este ciclo.
        const newlyUpdatedIds = [...new Set(nextUpdatedCells)].filter(id => {
             return estado[id] !== undefined; 
        });

        if (newlyUpdatedIds.length === 0) break;

        updatedCells = newlyUpdatedIds;
        currentDepth++;
    }
}
