function evalFormula(formula, estado) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return formula; // Not a formula or invalid format
    }

    let expression = formula.substring(1); // Remove leading '='

    // Regex to find cell references (e.g., A1, B20) - assuming standard Excel style coordinates
    const cellRegex = /([A-Z]+\d+)/g;

    // Replace all cell IDs with their numerical values from the current state.
    expression = expression.replace(cellRegex, (match) => {
        const value = estado[match];
        if (value === undefined || value === null) {
            return '0'; // Treat missing dependencies as 0 for calculation purposes
        }
        // Strip non-numeric characters except for decimal point and minus sign before parsing.
        const numericString = String(value).replace(/[^0-9.-]/g, '');
        const numericValue = parseFloat(numericString);
        return isNaN(numericValue) ? '0' : numericValue;
    });

    try {
        // Use Function constructor for safe evaluation of the resulting math string
        // This evaluates the mathematical expression using the current state values.
        return new Function('return ' + expression)();
    } catch (e) {
        console.error("Error evaluating formula:", e);
        return formula; // Return original formula if evaluation fails
    }
}
