```javascript
function actualizarCelda(cellId, value) {
    if (!estado.hasOwnProperty(cellId)) {
        console.warn(`Intento de actualizar una celda no inicializada: ${cellId}`);
        return;
    }
    // Actualizamos el estado con el valor recibido (el texto puro).
    estado[cellId] = value;
    guardar();
    // Después de la lógica, siempre renderizamos para asegurar que cualquier formato o cálculo se aplique.
    render();
}

function calculateFormula(cellId, formulaString, currentState) {
    // Esta función simula el motor de evaluación de fórmulas basado en la dependencia del estado.
    try {
        // Simplificación: Sustituye referencias como B1 por sus valores actuales en currentState.
        let expression = formulaString;
        const cellIds = Object.keys(currentState);

        for (const id of cellIds) {
            if (id !== cellId && typeof currentState[id] === 'string' && currentState[id].startsWith('=')) continue; // Skip formulas themselves

            // Regex para buscar referencias de celda como B1, C2 etc.
            expression = expression.replace(new RegExp(`([A-Z]+[0-9]+)`, 'g'), (match) => {
                const value = currentState[match];
                if (value === undefined || typeof value !== 'string') return match; // Si no existe en estado, mantener la referencia original

                // Evaluar si el valor es numérico para cálculos.
                return isNaN(parseFloat(value)) ? `'${value}'` : parseFloat(value);
            });
        }

        // Evaluación real usando eval() (solo porque estamos simulando un motor de cálculo simple)
        // En un entorno real, esto debería ser mucho más seguro y robusto.
        const result = Function(`return ${expression}`)();
        return isNaN(result) ? formulaString : String(result);

    } catch (e) {
        console.error("Error al calcular la fórmula:", e);
        return formulaString; // Devolver la fórmula si falla el cálculo
    }
}
