### FUNCION: conectar
```javascript
function conectar() {
    const spreadsheetBody = document.querySelector('tbody');
    const body = document.body; // Usamos el body para manejar eventos fuera de la tabla

    if (!spreadsheetBody) return;

    /**
     * Manejador genérico para cualquier cambio en las celdas editables.
     */
    const handleCellChange = (event) => {
        // 1. Identificar la celda que disparó el evento.
        const target = event.target;
        if (target.tagName !== 'TD' || !target.hasAttribute('data-cell')) {
            return;
        }

        const cellId = target.getAttribute('data-cell');
        // 2. Obtener el valor *real* que se quedó en el DOM después de la edición.
        let newValue = target.textContent.trim();

        // 3. Lógica: Actualizar el estado con el valor finalizado.
        actualizarCelda(cellId, newValue);
    };

    /**
     * Manejador de clic derecho para abrir el menú contextual.
     */
    const handleContextMenu = (event) => {
        // Evita el menú contextual nativo del navegador
        event.preventDefault(); 

        const target = event.target;
        if (target.tagName !== 'TD' || !target.hasAttribute('data-cell')) {
            return;
        }

        const cellId = target.getAttribute('data-cell');
        const menu = document.getElementById('context-menu');

        // 1. Posicionar y mostrar el menú
        menu.style.display = 'block';
        menu.style.left = `${event.clientX}px`;
        menu.style.top = `${event.clientY}px`;

        // 2. Configurar la lógica para seleccionar color (usando event delegation en el menu)
        const colorSwatches = document.querySelectorAll('.color-swatch');
        colorSwatches.forEach(swatch => {
            swatch.onclick = () => {
                const selectedColor = swatch.getAttribute('data-color');
                aplicarColorFondo(cellId, selectedColor);
                menu.style.display = 'none'; // Ocultar el menú después de la acción
            };
        });
    };

    // Eventos en las celdas (dentro del cuerpo)
    spreadsheetBody.addEventListener('blur', handleCellChange);
    spreadsheetBody.addEventListener('change', handleCellChange);

    // Evento global para el menú contextual (sobre el body, pero con lógica de celda)
    body.addEventListener('contextmenu', handleContextMenu);

    // Evento global para ocultar el menú si se hace clic en otro lugar
    document.addEventListener('click', (e) => {
        const menu = document.getElementById('context-menu');
        if (menu && e.target !== menu && !menu.contains(e.target)) {
            menu.style.display = 'none';
        }
    });
}
