```javascript
// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const spreadsheetContainer = document.getElementById('spreadsheet-container');
    const spreadsheetBody = document.querySelector('tbody');

    if (!spreadsheetBody || !spreadsheetContainer) return;

    /**
     * Manejador genérico para cualquier cambio en las celdas editables.
     * Solo se dispara cuando el usuario deja de escribir o termina de editar (blur/change).
     */
    const handleCellChange = (event) => {
        // 1. Identificar la celda que disparó el evento.
        const target = event.target;
        if (target.tagName !== 'TD' || !target.hasAttribute('data-cell')) {
            return;
        }

        const cellId = target.getAttribute('data-cell');
        // 2. Obtener el valor *real* que se quedó en el DOM después de la edición.
        let newValue = target.textContent.trim();

        // 3. Lógica: Actualizar el estado con el valor finalizado.
        actualizarCelda(cellId, newValue);
    };

    /**
     * Manejador para mostrar y aplicar color de fondo al hacer clic derecho en una celda.
     */
    const handleCellContextMenu = (event) => {
        // Evita el menú contextual por defecto del navegador
        event.preventDefault(); 

        const target = event.target;
        if (target.tagName !== 'TD' || !target.hasAttribute('data-cell')) {
            return;
        }

        // 1. Crear el menú contextual (Overlay)
        let menu = document.createElement('div');
        menu.className = 'context-menu';
        menu.style.position = 'absolute';
        menu.style.background = '#fff';
        menu.style.border = '1px solid #ccc';
        menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
        menu.style.zIndex = '1000';

        // Contenido del menú: Título y botones de color
        let htmlContent = `
            <div style="padding: 8px; font-weight: bold; border-bottom: 1px solid #eee;">Color de Fondo</div>
        `;
        const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF']; // Rojo, Verde, Azul, Amarillo, Magenta
        colors.forEach((color, index) => {
            htmlContent += `<button class="color-btn" data-color="${color}" style="background-color:${color}; color:black; border:none; padding:5px 10px; margin: 2px; cursor: pointer;">${index + 1}</button>`;
        });
        menu.innerHTML = htmlContent;

        // Posicionar el menú donde se hizo clic
        // Usamos clientX/Y para mayor robustez en posicionamiento absoluto global
        menu.style.left = `${event.clientX}px`;
        menu.style.top = `${event.clientY}px`;

        // 2. Mostrar el menú y añadir listeners para seleccionar color
        document.body.appendChild(menu);

        const buttons = menu.querySelectorAll('.color-btn');
        buttons.forEach(button => {
            button.addEventListener('click', (e) => {
                const selectedColor = e.currentTarget.getAttribute('data-color');
                // Aplicar el color de fondo al DOM del TD
                target.style.backgroundColor = selectedColor;

                menu.remove(); // Limpiar el menú después de la selección
            });
        });

        // 3. Listener para cerrar el menú al hacer clic fuera
        document.addEventListener('click', function clickOutsideHandler(e) {
            if (!menu.contains(e.target)) {
                menu.remove();
                document.removeEventListener('click', clickOutsideHandler); // Limpiar listener
            }
        }, { once: true }); 
    };


    // Usamos Event Delegation para escuchar eventos sobre todos los TDs sin adjuntar listeners individuales.
    spreadsheetBody.addEventListener('blur', handleCellChange);
    spreadsheetBody.addEventListener('change', handleCellChange);

    // Añadimos el listener de contexto al contenedor completo
    spreadsheetContainer.addEventListener('contextmenu', handleCellContextMenu);
}
