### ARCHIVO: script.js
```javascript
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
let estado = {};
const CLAVE = "app";
const TOTAL_FILAS = 20;
const COLUMNAS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

// Variable para rastrear la columna seleccionada actualmente.
let selectedColumnLetter = null;


// Inicializa el estado con todas las celdas vacías, pero presentes.
function inicializarEstado() {
    estado = {};
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        for (const col of COLUMNAS) {
            const cellId = `${col}${r}`;
            estado[cellId] = ''; // Inicializa cada celda con un valor vacío
        }
    }
}

/**
 * Actualiza el estado interno de una celda específica.
 * @param {string} cellId - ID de la celda (Ej: 'A1').
 * @param {string} value - El nuevo valor ingresado por el usuario.
 */
function actualizarCelda(cellId, value) {
    if (!estado.hasOwnProperty(cellId)) {
        console.warn(`Intento de actualizar una celda no inicializada: ${cellId}`);
        return;
    }
    // Actualizamos el estado con el valor recibido (el texto puro).
    estado[cellId] = value;
    guardar();
    // Después de la lógica, siempre renderizamos para asegurar que cualquier formato o cálculo se aplique.
    render();
}


function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            const loadedState = JSON.parse(s);
            // Aseguramos que el estado cargado tenga la estructura completa, rellenando lo faltante.
            inicializarEstado();
            for (const cellId in loadedState) {
                if (loadedState.hasOwnProperty(cellId)) {
                    estado[cellId] = loadedState[cellId];
                }
            }
        } else {
             // Si no hay datos guardados, inicializamos el estado vacío completo.
            inicializarEstado();
        }
    } catch (e) { 
        console.error("Error al cargar el estado:", e);
        inicializarEstado(); // Fallback seguro
    } 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) { 
        console.error("Error al guardar el estado:", e); 
    } 
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('td[data-cell]');

    cells.forEach(cell => {
        const cellId = cell.getAttribute('data-cell');
        const currentValueInState = estado[cellId];

        // Regla: No redibujar si el elemento está activo (el usuario lo está editando).
        if (document.activeElement === cell) {
            return; 
        }

        // Establecer el contenido visible del TD desde el estado.
        // Usamos innerText o textContent para evitar que la manipulación de innerHTML cause problemas con contenteditable.
        cell.textContent = currentValueInState;
    });
}


// ===== LÓGICA DE COLUMNAS: Manejo de interacciones avanzadas (R6) =====

/**
 * Limpia el contenido de todas las celdas en una columna específica.
 * @param {string} letter - Letra de la columna (Ej: 'A').
 */
function clearColumnContent(letter) {
    let cellsToClear = [];
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        const cellId = `${letter}${r}`;
        if (estado.hasOwnProperty(cellId)) {
            estado[cellId] = ''; // Limpiar el estado
            cellsToClear.push(document.querySelector(`td[data-cell="${cellId}"]`));
        }
    }

    // Limpiar visualmente los elementos del DOM
    cellsToClear.forEach(cell => {
        cell.textContent = '';
    });
    guardar();
    render();
}


/**
 * Cambia el color de fondo de todas las celdas en una columna específica.
 * @param {string} letter - Letra de la columna (Ej: 'A').
 */
function changeColumnColor(letter) {
    const color = prompt("Ingrese el color deseado (ej: #FFCC00, red):", "#ffffcc");
    if (!color) return;

    let cellsAffected = [];
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        const cellId = `${letter}${r}`;
        const cellElement = document.querySelector(`td[data-cell="${cellId}"]`);
        if (cellElement) {
            // Aplicar el color de fondo directamente al elemento DOM
            cellElement.style.backgroundColor = color;
            cellsAffected.push(cellElement);
        }
    }
    // Nota: No se actualiza el estado, solo el estilo visual.
    guardar(); 
    render(); // Re-renderizar para asegurar que el cambio de fondo persista si hay otras interacciones.
}


/**
 * Elimina una columna completamente (DOM y estado).
 * @param {string} letter - Letra de la columna a eliminar.
 */
function deleteColumn(letter) {
    if (!confirm(`¿Está seguro de que desea borrar la columna ${letter}? Esta acción es irreversible.`)) {
        return;
    }

    let cellsToRemove = [];
    // 1. Eliminar celdas del DOM y actualizar el estado
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        const cellId = `${letter}${r}`;
        if (estado.hasOwnProperty(cellId)) {
            delete estado[cellId]; // Limpiar el estado
            const cellElement = document.querySelector(`td[data-cell="${cellId}"]`);
            if (cellElement) {
                cellsToRemove.push(cellElement);
            }
        }
    }

    // 2. Eliminar las celdas del DOM
    cellsToRemove.forEach(element => element.remove());

    // 3. Eliminar el encabezado de la columna
    const header = document.querySelector(`.col-header[data-column-letter="${letter}"]`);
    if (header) {
        header.remove();
    }

    guardar();
    render(); // Redibujar para reflejar los cambios estructurales
    selectedColumnLetter = null; // Deseleccionar columna
    console.log(`Columna ${letter} eliminada exitosamente.`);
}


// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const spreadsheetBody = document.querySelector('tbody');

    if (!spreadsheetBody) return;

    /**
     * Manejador genérico para cualquier cambio en las celdas editables.
     */
    const handleCellChange = (event) => {
        // 1. Identificar la celda que disparó el evento.
        const target = event.target;
        if (target.tagName !== 'TD' || !target.hasAttribute('data-cell')) {
            return;
        }

        const cellId = target.getAttribute('data-cell');
        // 2. Obtener el valor *real* que se quedó en el DOM después de la edición.
        let newValue = target.textContent.trim();

        // 3. Lógica: Actualizar el estado con el valor finalizado.
        actualizarCelda(cellId, newValue);
    };


    // Usamos Event Delegation para escuchar eventos sobre todos los TDs sin adjuntar listeners individuales.
    spreadsheetBody.addEventListener('blur', handleCellChange);
    spreadsheetBody.addEventListener('change', handleCellChange);

    /**
     * Manejador principal de clics en el encabezado (col-header).
     */
    document.getElementById('header-row').addEventListener('click', function(e) {
        const target = e.target;
        // Si se hizo clic en un botón de control, no queremos que se dispare la lógica principal de columna.
        if (target.closest('.column-controls')) return; 

        let headerTh = target.closest('.col-header');
        if (!headerTh) return;

        const letter = headerTh.getAttribute('data-column-letter');
        selectColumn(letter);
    });
}


/**
 * Selecciona visualmente una columna y la establece como seleccionada en el estado interno.
 * @param {string} letter - Letra de la columna (Ej: 'A').
 */
function selectColumn(letter) {
    // Deseleccionar todas las columnas primero
    document.querySelectorAll('.col-header').forEach(th => th.classList.remove('selected-column'));

    if (selectedColumnLetter === letter) {
        // Si ya está seleccionada, no hacemos nada o deseleccionamos si es un click secundario/toggle
        return; 
    }

    selectedColumnLetter = letter;
    const selectedHeader = document.querySelector(`.col-header[data-column-letter="${letter}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected-column');
        // Aquí podríamos mostrar un panel de opciones si fuera necesario, pero por ahora solo seleccionamos visualmente.
    }
}

/**
 * Muestra los controles avanzados en el encabezado de columna seleccionado.
 * @param {string} letter - Letra de la columna a interactuar.
 */
function showColumnControls(letter) {
    // 1. Seleccionar la columna primero (para que la lógica sepa qué hacer).
    selectColumn(letter);

    // 2. Obtener el contenedor de controles y construir/mostrar botones.
    const controlsDiv = document.querySelector(`.col-header[data-column-letter="${letter}"] .column-controls`);
    if (!controlsDiv) return;

    // Limpiar contenidos anteriores
    controlsDiv.innerHTML = `
        <button onclick="clearColumnContent('${letter}')" style="background-color: #ffdddd;">🗑️ Borrar Contenido</button>
        <button onclick="changeColumnColor('${letter}')" style="background-color: #ddffff;">🎨 Color Fondo</button>
        <button onclick="deleteColumn('${letter}')" style="background-color: #ffaaaa; color: red;">❌ Eliminar Columna</button>
    `;

    // 3. Añadir un listener para que el click en la letra también pueda mostrar los controles si se quiere mejorar la UX, 
    // pero por ahora nos basamos en el botón '...' visible en el HTML modificado.
}


// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
