    const cellsToRemove = document.querySelectorAll(`td[data-cell^="${columnLetter}"]`);
    cellsToRemove.forEach(cell => cell.remove());

    // 3. Ajustar el contenido de los encabezados de columna (si se elimina una columna, las letras siguientes deben reajustarse).
