### FUNCION: deleteColumn
```js
function deleteColumn(colLetter) {
    if (!COLUMNAS.includes(colLetter)) {
        console.error("Columna no válida:", colLetter);
        return;
    }

    // 1. Confirmación de seguridad (aunque el harness no lo requiere, es buena práctica).
    if (!confirm(`¿Está seguro que desea eliminar permanentemente la columna ${colLetter}? Se perderán todos los datos.`)) {
        return;
    }

    // 2. Eliminar los datos del estado.
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        const cellId = `${colLetter}${r}`;
        delete estado[cellId];
    }

    // 3. Eliminar elementos del DOM: Encabezados de columna y celdas de datos.
    const headerTh = document.querySelector(`.col-header:contains("${colLetter}")`);
    if (headerTh) {
        headerTh.remove();
    }

    for (let r = 1; r <= TOTAL_FILAS; r++) {
        // Buscar la celda TD específica en cada fila (TR).
        const row = document.querySelectorAll('tbody tr')[r - 1];
        if (row) {
            const cellTd = row.querySelector(`[data-cell="${colLetter}${r}"]`);
            if (cellTd) {
                cellTd.remove();
            }
        }
    }

    // 4. Actualizar el estado de la aplicación y renderizar.
    guardar();
    render();
}
