### FUNCION: deleteColumn
```js
function deleteColumn() {
    const colLetter = estado.selectedColumn;
    if (!colLetter) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }

    if (!confirm(`¿Estás seguro de que deseas eliminar la Columna ${colLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Actualizar el estado: Eliminar todas las celdas de esa columna.
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        const cellId = `${colLetter}${r}`;
        if (estado.hasOwnProperty(cellId)) {
            delete estado[cellId];
        }
    }

    // 2. Limpiar la selección y el DOM: Reconstruir las columnas visibles.
    estado.selectedColumn = null;
    document.querySelectorAll('.col-header').forEach(th => th.classList.remove('selected'));

    const container = document.getElementById('spreadsheet-container');
    // Guardar el contenido de la tabla para reconstruirla en lugar de borrarla directamente (más seguro)
    let originalHTML = container.innerHTML; 
    container.innerHTML = ''; // Limpiar y reconstruir

    // Reconstruir el thead con las columnas restantes
    const newThead = document.createElement('thead');
    newThead.innerHTML = `<tr><th></th class="col-header">${COLUMNAS.filter(c => c !== colLetter).join('<th class="col-header"></th>') || ''}</th></tr>`;
    container.appendChild(newThead);

    // Reconstruir el tbody con las celdas restantes
    let rowsHTML = '';
    for (let r = 1; r <= TOTAL_FILAS; r++) {
        const rowCells = [];
        for (const col of COLUMNAS.filter(c => c !== colLetter)) {
            rowCells.push(`<td contenteditable="true" data-cell="${col}${r}"></td>`);
        }
        rowsHTML += `<tr><th>${r}</th>${rowCells.join('')}</tr>`;
    }

    const newTbody = document.createElement('tbody');
    newTbody.innerHTML = rowsHTML;
    container.appendChild(newTbody);


    // 3. Actualizar el estado y la vista
    guardar();
    render();
    conectar(); // Re-establecer listeners en los nuevos elementos

    alert(`Columna ${colLetter} eliminada correctamente.`);
}
