 * @param {string} columnLetter - La letra de la columna (Ej: 'A').
 * @param {boolean} shouldHide - Si es true, oculta; si es false, muestra.
 */
function toggleColumnVisibility(columnLetter, shouldHide) {
    const cells = document.querySelectorAll(`td[data-cell^='${columnLetter}']`);
    let isCurrentlyHidden = !shouldHide;

    cells.forEach(cell => {
        if (shouldHide && cell.style.display !== 'none') {
            // Ocultar: Aplicar estilo display: none al elemento y ajustar su ancho si es necesario.
            cell.style.display = 'none';
        } else if (!shouldHide && cell.style.display === 'none') {
            // Mostrar: Eliminar el estilo de ocultamiento para que la columna reaparezca.
            cell.style.display = ''; 
        }
    });

    // Nota importante: Al esconder/mostrar, el estado interno (estado[cellId]) debe mantenerse sin cambios.
    // Solo ajustamos la visibilidad en el DOM.
}
