### FUNCION: toggleColumnVisibility
```js
function toggleColumnVisibility(columnElement, isHidden) {
    const columnLetter = columnElement.textContent.trim();
    if (!columnLetter || !/[A-Z]/.test(columnLetter)) return; // Only process valid headers

    // 1. Toggle the header visibility itself
    const header = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (header) {
        header.classList.toggle('hidden', isHidden);
    } else if (columnElement.classList.contains('col-header')) {
         // Fallback for the initial structure where data-column might not be set
         columnElement.classList.toggle('hidden', isHidden);
    }


    // 2. Toggle visibility on all data cells (TDs) in every row
    const allCells = document.querySelectorAll('td[data-cell]');

    allCells.forEach(cell => {
        // Assuming the column order matches the header letter position A=0, B=1...
        // We need to find which column this cell belongs to based on its parent's index relative to other Tds in a row.
        // Since we are operating on the whole table structure:

        const cellsInRow = Array.from(cell.closest('tr').querySelectorAll('td'));
        const columnIndex = cellsInRow.findIndex(c => c === cell); // Index 1, 2, 3... for A, B, C... (skipping row index TH)

        // Check if this column matches the target column based on its calculated position/letter
        // This is complex due to fixed table layout. Let's rely on relative positioning:
        const headerCells = document.querySelectorAll('.col-header');
        let targetColIndex = -1;
        for(let i=0; i < headerCells.length; i++) {
            if (headerCells[i].textContent.trim() === columnLetter) {
                targetColIndex = i;
                break;
            }
        }

        // If the target cell's index matches the current column being toggled:
        if (columnIndex === targetColIndex) { 
             cell.classList.toggle('hidden', isHidden);
        }
    });

    guardar();
    render(); // Redibujar para asegurar que el estado visual de los bordes y la estructura es correcto
}
