        const color = window.getComputedStyle(document.body).backgroundColor; // Usamos un color visible o predefinido
        cells.forEach(cell => {
            cell.style.backgroundColor = '#ffffe0'; // Un amarillo claro para indicar el cambio
        });
    } else if (action === 'delete') {
        // Borrar la fila completa del DOM y del estado global.
        if (confirm(`¿Está seguro de que desea eliminar la fila ${rowIndex}?`)) {
            const cellsToDelete = Array.from(rowElement.querySelectorAll('td'));

            cellsToDelete.forEach(cell => {
                const cellId = cell.getAttribute('data-cell');
                delete estado[cellId]; // Eliminar del estado global
            });

            // Remover la fila del DOM
            rowElement.remove();
            guardar();
            render(); // Redibujar para asegurar que el estado de las celdas restantes es correcto
        }
    } else if (action === 'hide') {
        // Ocultar la fila completa en el DOM y registrarla en el estado.
        if (!confirm(`¿Está seguro de que desea ocultar completamente la fila ${rowIndex}?`)) return;

        // 1. Actualizar el estado para marcar la fila como oculta.
        estado.isHiddenRows.add(rowIndex);

        // 2. Ocultar en el DOM aplicando una clase CSS.
        rowElement.classList.add('hidden-row');
        guardar();
        render(); // Redibujar para asegurar que los elementos visibles se actualicen correctamente
    } else if (action === 'show') {
        // Mostrar la fila completa en el DOM y eliminarla del estado de ocultamiento.
        if (!confirm(`¿Está seguro de que desea mostrar completamente la fila ${rowIndex}?`)) return;

        // 1. Eliminar el registro de ocultamiento.
        estado.isHiddenRows.delete(rowIndex);

        // 2. Mostrar en el DOM.
        rowElement.classList.remove('hidden-row');
        guardar();
        render();
    }
}
