### FUNCION: calculateFormula
```javascript
/**
 * Evalúa fórmulas simples de suma en un formato tipo hoja de cálculo.
 * Soporta sintaxis =SUMA(ID1;ID2;...)
 * @param {string} formulaString - El valor ingresado (debe empezar con '=').
 * @param {string} callingCellId - ID de la celda que contiene la fórmula.
 * @returns {number|null} El resultado calculado, o null si no es una suma válida o falla el cálculo.
 */
function calculateFormula(formulaString, callingCellId) {
    const formula = formulaString.toUpperCase().trim();

    if (!formula.startsWith('=')) {
        return null; // No es una fórmula detectada por este manejador
    }

    // Buscamos patrones de SUMA(Argumentos...)
    if (formula.includes("SUMA")) {
        const match = formula.match(/=SUMA\((.*)\)/i);
        if (!match) return null;

        const argumentsString = match[1]; // Contiene "ID1;ID2;..."
        const cellIds = argumentsString.split(';')
                                     .map(id => id.trim())
                                     .filter(id => id.length > 0);

        let totalSum = 0;
        let validCellsCount = 0;

        for (const cellId of cellIds) {
            // Ignoramos que la fórmula se refiera a sí misma.
            if (cellId === callingCellId) continue;

            const value = estado[cellId];
            if (value !== undefined && value !== '') {
                const numericValue = parseFloat(value);
                if (!isNaN(numericValue)) {
                    totalSum += numericValue;
                    validCellsCount++;
                } else {
                    // Si un argumento no es numérico, asumimos que el cálculo falla o debe ignorarse.
                    console.warn(`Argumento ${cellId} en la fórmula no es numérico.`);
                }
            }
        }

        return totalSum;
    }

    return null; // Fórmula desconocida
}
